"""Text-to-SQL harness: draft -> execute -> targeted repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task (env.max_calls)
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'([^']*)'")
IDENT = re.compile(r"\b([A-Za-z_][A-Za-z_0-9]*)\b")
STOP = set(
    """select from where and or not in is null like as join left right inner outer on
    group by order having limit offset distinct count sum avg min max case when then else end
    union all intersect except exists between asc desc collate nocase cast int integer text real
    with recursive true false escape glob instr substr lower upper length coalesce ifnull round
    abs date strftime julianday char replace trim ltrim rtrim natural cross using values over
    partition row_number rank dense_rank sqlite primary key foreign references create table view
    index default check unique constraint autoincrement varchar boolean datetime numeric float
    double decimal blob t1 t2 t3 t4 t5 a b c d e""".split()
)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    txt = (text or "").strip()
    m = re.search(r"(?is)\b(select|with)\b.*", txt)
    if m:
        txt = m.group(0)
    return txt.rstrip(";").strip()


def _tables_columns(schema):
    """{table_lower: [column, ...]} parsed from CREATE statements."""
    out = {}
    for m in re.finditer(r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?([\w ]+?)[\"'`\]]?\s*\((.*)", schema or "", re.I | re.S):
        name = m.group(1).strip().lower()
        body = m.group(2)
        depth, end = 0, len(body)
        for i, ch in enumerate(body):
            if ch == "(":
                depth += 1
            elif ch == ")":
                if depth == 0:
                    end = i
                    break
                depth -= 1
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body[:end]:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            if not p:
                continue
            first = p.split()[0].strip('"`[]\'')
            if first.lower() in ("primary", "foreign", "unique", "check", "constraint"):
                continue
            cols.append(first)
        out[name] = cols
    return out


def _probe(env, schema, sql, budget=3):
    """Cheap evidence about the real stored values behind the draft's filters."""
    tc = _tables_columns(schema)
    if not tc:
        return ""
    used_tables = []
    idents = {t.lower() for t in IDENT.findall(sql)}
    for t in tc:
        if t in idents or t.replace(" ", "_") in idents:
            used_tables.append(t)
    lits = [s.strip() for s in LITERAL.findall(sql) if s.strip()]
    lines = []
    for lit in lits[:2]:
        toks = [w for w in re.findall(r"[A-Za-z0-9]{3,}", lit)]
        if not toks:
            continue
        tok = max(toks, key=len)
        for t in used_tables:
            for c in tc[t]:
                if budget <= 0:
                    break
                q = 'SELECT DISTINCT "%s" FROM "%s" WHERE "%s" LIKE \'%%%s%%\' COLLATE NOCASE LIMIT 6' % (c, t, c, tok)
                r = env.execute(q, max_rows=6)
                budget -= 1
                if r.get("ok") and r.get("rows"):
                    vals = [str(x[0]) for x in r["rows"]]
                    lines.append("Actual stored values in %s.%s matching %r: %s" % (t, c, tok, "; ".join(vals)))
                    break
            if lines and lines[-1].find(tok) >= 0:
                break
    # sample low-cardinality text columns of the tables the draft touches
    for t in used_tables[:2]:
        for c in tc[t][:14]:
            if budget <= 0:
                break
            q = 'SELECT DISTINCT "%s" FROM "%s" LIMIT 8' % (c, t)
            r = env.execute(q, max_rows=8)
            budget -= 1
            if not r.get("ok"):
                continue
            vals = [x[0] for x in r.get("rows", [])]
            if vals and all(isinstance(v, str) for v in vals) and len(vals) <= 8:
                short = "; ".join(repr(v) for v in vals)
                if len(short) < 220:
                    lines.append("Sample values of %s.%s: %s" % (t, c, short))
    return "\n".join(lines[:8])


def solve(task, env):
    cfg = env.config
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s" % (task["db_id"], schema)
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:3000]
    user += "\n\nQuestion: " + task["question"]
    if task.get("hint"):
        user += "\nHint: " + task["hint"]
    system = env.prompt("system_prompt.md")
    messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
    reply = env.chat(messages, max_tokens=cfg.get("max_tokens", 800))
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    res = env.execute(sql, max_rows=20)
    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", 0) if ok else 0
    needs_fix = (not ok) or nrows == 0
    if not needs_fix:
        return {"sql": sql}

    if ok:
        feedback = (
            "Your query executed but returned 0 rows. That almost always means a filter does not match "
            "how values are stored (extra spaces, different casing/abbreviation, wrong column, wrong join "
            "direction), or the question's requested output shape was misread.\n"
            "Re-read the question: if it asks about whole entities without naming attributes, select all "
            "columns of the main table (T1.*). Loosen brittle equality to LIKE '%trimmed phrase%' and use "
            "the real stored values shown below."
        )
    else:
        feedback = "Your query failed with error: %s\nFix the syntax/schema issue." % str(res.get("error"))[:400]

    evidence = ""
    try:
        evidence = _probe(env, schema, sql)
    except Exception:
        evidence = ""
    if evidence:
        feedback += "\n\nEvidence from the database:\n" + evidence

    feedback += (
        "\n\nRewrite the query so it correctly answers the question. Keep the same intent; change only what "
        "is wrong. Return the corrected query in a single ```sql code block."
    )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": feedback},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=cfg.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = env.execute(sql2, max_rows=20)
    if res2.get("ok"):
        return {"sql": sql2}
    return {"sql": sql}

